                <set-variable name="rdwrCloudProjected" value="@{
                  try {
                    if (!context.Variables.ContainsKey("rdwrCloudResp") || context.Variables["rdwrCloudResp"] == null) { return ""; }
                    var resp = (IResponse)context.Variables["rdwrCloudResp"];
                    if (resp.StatusCode != 200) { return ""; }
                    JToken root = resp.Body.As();
                    JArray apps = root as JArray;
                    if (apps == null && root is JObject) { apps = (root["content"] as JArray) ?? (root["applications"] as JArray); }
                    if (apps == null) { return ""; }
                    var map = new JObject();
                    foreach (JToken a in apps) {
                      if ((string)a["applicationAssetType"] != "OUT_OF_PATH") { continue; }
                      if ((string)a["deploymentStatus"] != "PROTECTING") { continue; }
                      string id = (string)a["id"];
                      string key = (string)a["oopApiKey"];
                      JToken waf = a["featuresData"] == null ? null : a["featuresData"]["wafFeatureData"];
                      if (waf == null) { continue; }
                      string domain = waf["mainDomain"] == null ? null : (string)waf["mainDomain"]["mainDomain"];
                      string cname = null;
                      JArray recs = waf["oopDns"] == null ? null : waf["oopDns"]["dnsRecords"] as JArray;
                      if (recs != null) {
                        foreach (JToken r in recs) {
                          if ((string)r["type"] == "CNAME" && !string.IsNullOrEmpty((string)r["value"])) { cname = ((string)r["value"]).Trim().ToLower(); break; }
                        }
                      }
                      if (string.IsNullOrEmpty(id) || string.IsNullOrEmpty(key) || string.IsNullOrEmpty(domain) || string.IsNullOrEmpty(cname)) { continue; }
                      var entry = new JObject();
                      entry["app_id"] = id;
                      entry["api_key"] = key;
                      entry["endpoint"] = cname;
                      entry["port"] = 443;
                      entry["ssl"] = true;
                      map[domain.Trim().ToLower()] = entry;
                      JToken apiHost = (a["apiProtection"] == null) ? null : a["apiProtection"]["hostname"];
                      if (apiHost != null && apiHost["useDefault"] != null && !(bool)apiHost["useDefault"] && !string.IsNullOrEmpty((string)apiHost["hostname"])) {
                        map[((string)apiHost["hostname"]).Trim().ToLower()] = entry;
                      }
                    }
                    return map.Count == 0 ? "" : map.ToString(Newtonsoft.Json.Formatting.None);
                  } catch { return ""; }
                }" />










